    "type": "string"
  },
  "required": true,
  "description": "An identifier for the software statement calling the API"
}

{
  "name": "o3-api-uri",
  "in": "header",
  "schema": {
    "type": "string"
  },
  "required": true,
  "description": "The parameterised URL of the API being called by the caller"
}

{
  "name": "o3-api-operation",
  "in": "header",
  "schema": {
    "type": "string"
  },
  "required": true,
  "description": "The API operation carried out by the caller (e.g. GET, POST, PUT, DELETE, PATCH)"
}

{
  "name": "o3-caller-interaction-id",
  "in": "header",
  "schema": {
    "type": "string"
  },
  "required": false,
  "description": "The interaction ID passed in by the caller, if any"
}

{
  "name": "o3-ozone-interaction-id",
  "in": "header",
  "schema": {
    "type": "string"
  },
  "required": true,
  "description": "An interaction ID generated by Ozone if the caller did not send in one. If the callerInteractionId is specified, this takes the same value."
}

{
  "name": "page",
  "in": "query",
  "description": "Page of results to request (standard pagination)",
  "required": true,
  "schema": {
    "default": 1,
    "type": "integer"
  },
  "style": "form"
}

{
  "name": "page-size",
  "in": "query",
  "description": "Page size to request. Default is 100 to comply with the Operating Guidelines for the Open Finance Framework.",
  "required": true,
  "schema": {
    "default": 100,
    "type": "integer"
  },
  "style": "form"
}

{
  "type": "object",
  "properties": {
    "data": {
      "type": "object",
      "properties": {
        "account": {
          "type": "object",
          "required": [
            "schemeName",
            "identification"
          ],
          "properties": {
            "schemeName": {
              "type": "string",
              "enum": [
                "IBAN"
              ],
              "description": "Name of the identification scheme for the account. Encoded with allowable values published in an external list."
            },
            "identification": {
              "type": "string",
              "description": "Identification for the account assigned by the LFI based on the Account Scheme Name. This identification is known by the User account owner. For IBAN, refer to the ISO Standard 13616."
            }
          },
          "description": "The account the Confirmation of Payee query is about, identified by IBAN. From v2.2 the name the TPP submitted is NOT sent to the LFI — the LFI returns the name(s) it holds against this account, and the API Hub compares them."
        }
      },
      "description": "Primary data for the resource."
    }
  },
  "description": "Properties of a Confirmation of Payee request"
}

{
  "type": "object",
  "properties": {
    "data": {
      "type": "array",
      "items": {
        "$ref": "#/components/schemas/CbuaeCopCustomer"
      },
      "description": "Primary data for the resource"
    },
    "meta": {
      "$ref": "#/components/schemas/Meta"
    }
  },
  "description": "The properties of a Confirmation of Payee query response"
}

{
  "description": "One account holder returned for a Confirmation of Payee query.\nA joint account returns one entry per holder. The API Hub evaluates EVERY entry in `data` — returning the holders in any order is safe, and the LFI MUST NOT attempt to order them by likelihood of match.\n",
  "type": "object",
  "required": [
    "id",
    "name"
  ],
  "additionalProperties": false,
  "properties": {
    "id": {
      "description": "A unique and immutable identifier used to identify the customer resource. This identifier has no meaning to the account owner.",
      "type": "string",
      "minLength": 1,
      "maxLength": 40
    },
    "name": {
      "description": "The name held against the account for this holder — a personal name or a business name.",
      "oneOf": [
        {
          "$ref": "#/components/schemas/CbuaeCopPersonName"
        },
        {
          "$ref": "#/components/schemas/CbuaeCopBusinessName"
        }
      ]
    }
  }
}

{
  "description": "The name of a personal account holder, as held by the LFI.\n`fullName` is the only required field and is what the API Hub matches on today. The remaining fields are OPTIONAL and are not required for a match to succeed — supply them where your systems hold them separately, so that improvements to the matching algorithm can use them without a further change to this contract.\n",
  "type": "object",
  "required": [
    "fullName"
  ],
  "additionalProperties": false,
  "properties": {
    "fullName": {
      "description": "The full name of the account holder, as it appears on the account, as a single string.",
      "type": "string",
      "minLength": 1,
      "maxLength": 140
    },
    "firstName": {
      "description": "Given name of the account holder. Optional. Named `firstName` rather than the v2.1 `givenName`, which the v2.1 schema already recorded as withdrawn.",
      "type": "string",
      "minLength": 1,
      "maxLength": 70
    },
    "middleName": {
      "description": "Middle name(s) of the account holder. Optional.",
      "type": "string",
      "minLength": 1,
      "maxLength": 70
    },
    "lastName": {
      "description": "Family name of the account holder. Optional. Named `lastName` rather than the v2.1 `familyName`, which the v2.1 schema already recorded as withdrawn.",
      "type": "string",
      "minLength": 1,
      "maxLength": 70
    },
    "fullNameAr": {
      "description": "The full name of the account holder in Arabic script, where the LFI holds one. Optional. Not matched today.",
      "type": "string",
      "minLength": 1,
      "maxLength": 140
    },
    "alsoKnownAs": {
      "description": "Other names the account is legitimately known by — for example a maiden name, or a transliteration variant the LFI holds. Optional. Not matched today.",
      "type": "array",
      "items": {
        "type": "string",
        "minLength": 1,
        "maxLength": 140
      }
    }
  }
}

{
  "description": "The name of a business account holder, as held by the LFI.\n`businessName` is the only required field and is what the API Hub matches on today. The remaining fields are OPTIONAL inputs to future matching.\n",
  "type": "object",
  "required": [
    "businessName"
  ],
  "additionalProperties": false,
  "properties": {
    "businessName": {
      "description": "The registered business name on the account.",
      "type": "string",
      "minLength": 1,
      "maxLength": 140
    },
    "businessNameAr": {
      "description": "The registered business name in Arabic script, where the LFI holds one. Optional. Not matched today.",
      "type": "string",
      "minLength": 1,
      "maxLength": 140
    },
    "alsoKnownAs": {
      "description": "Other names the business is legitimately known by — for example a trading name distinct from the registered name. Optional. Not matched today.",
      "type": "array",
      "items": {
        "type": "string",
        "minLength": 1,
        "maxLength": 140
      }
    }
  }
}

{
  "type": "object",
  "properties": {
    "totalPages": {
      "type": "number",
      "description": "The number of expected pages for the query.\n"
    },
    "totalRecords": {
      "type": "number",
      "description": "The total number of records in the full set.\n"
    }
  },
  "description": "Metadata relevant to the resource."
}

{
  "description": "Operation failed due to a invalid request parameter",
  "content": {
    "application/json": {
      "schema": {
        "$ref": "#/components/schemas/Error400"
      }
    }
  }
}

{
  "description": "Default error response payload structure for Ozone Connect",
  "type": "object",
  "required": [
    "errorCode",
    "errorMessage"
  ],
  "properties": {
    "errorCode": {
      "description": "Error code identifying the problem that occurred. This may either be one of the prescribed Error Code(s) or a namespaced Error Code where the namespace is the system or organisation that has responded with the error, and the code is the code specific to the system or organisation. organisation or system.\nLFIs should implement error codes based on the prescribed codes or guidance in the standards, with non-specific codes maintained for backward compatibility with version 1.2.",
      "anyOf": [
        {
          "type": "string",
          "enum": [
            "Consent.Invalid",
            "Consent.BusinessRuleViolation",
            "Consent.FailsControlParameters",
            "Consent.InvalidUserIdentifier",
            "JWS.InvalidSignature",
            "JWS.Malformed",
            "JWS.InvalidClaim",
            "JWS.InvalidHeader",
            "JWE.DecryptionError",
            "JWE.InvalidHeader",
            "GenericRecoverableError",
            "GenericError",
            "Event.UnexpectedEvent",
            "Body.InvalidFormat",
            "Resource.InvalidFormat"
          ]
        },
        {
          "type": "string",
          "pattern": "^[A-Za-z]+\\.[A-Za-z0-9]+$"
        },
        {
          "type": "string"
        }
      ]
    },
    "errorMessage": {
      "$ref": "#/components/schemas/ErrorMessage"
    }
  }
}

{
  "description": "Message describing the problem that has occurred.",
  "type": "string"
}

{
  "description": "Operation failed due to an invalid credential or missing token",
  "content": {
    "application/json": {
      "schema": {
        "type": "object",
        "properties": {
          "errorCode": {
            "description": "Error code identifying the problem that occurred. Should be implemented based on guidance in standards and API Hub documentation, but custom error code lists maintained for backwards compatibility with v1.2.",
            "type": "string"
          },
          "errorMessage": {
            "$ref": "#/components/schemas/ErrorMessage"
          }
        }
      }
    }
  }
}

{
  "description": "Operation failed as access to the requested resource is forbidden",
  "content": {
    "application/json": {
      "schema": {
        "$ref": "#/components/schemas/Error403"
      }
    }
  }
}

{
  "description": "Error code identifying the problem that occurred. The first part of the code is the namespace, which is the name of the organisation or system that is rejecting the payment, and the second part is the specific rejection reason code for the originating organisation or system.\nLFIs should implement error codes based on the prescribed codes or guidance in the standards, with non-specific codes maintained for backward compatibility with version 1.2.",
  "type": "object",
  "required": [
    "errorCode",
    "errorMessage"
  ],
  "properties": {
    "errorCode": {
      "description": "Error code identifying the problem that occurred. This may either be one of the prescribed Error Code(s) or a namespaced Error Code where the namespace is the system or organisation that has responded with the error, and the code is the code specific to the system or organisation.",
      "anyOf": [
        {
          "type": "string",
          "enum": [
            "AccessToken.InvalidScope",
            "Consent.TransientAccountAccessFailure",
            "Consent.AccountTemporarilyBlocked",
            "Consent.PermanentAccountAccessFailure",
            "GenericRecoverableError",
            "GenericError"
          ]
        },
        {
          "type": "string",
          "pattern": "^[A-Za-z]+\\.[A-Za-z0-9]+$"
        },
        {
          "type": "string"
        }
      ]
    },
    "errorMessage": {
      "$ref": "#/components/schemas/ErrorMessage"
    }
  }
}

